# MLP direct logit attribution at key positions
import numpy as np, torch, json
D = "/work/fwd_2"
meta = json.load(open(f"{D}/meta.json"))
lengths = meta["lengths"]; tids = meta["token_ids"]
H = np.load(f"{D}/hidden_L24.npy").astype(np.float32)   # [texts, pos, hidden]
print("H", H.shape, H.dtype)
gamma = load("model.language_model.norm.weight").float().numpy()   # [1024]
E = load("model.language_model.embed_tokens.weight").float().numpy()
TOK = {"</think>":248069, "<|im_end|>":248046, "<|endoftext|>":248044, "<think>":248068}

def rms(h):
    return np.sqrt((h**2).mean(-1))

def R(T):
    return E[T]*(1.0+gamma)

for name, T in TOK.items():
    r = R(T)
    dots = np.array([np.dot(r, H[t, p]) for t in range(5) for p in [lengths[t]-1]])
    print(name, "dot at final pos texts0-4:", dots, "rms:", [round(float(rms(H[t, lengths[t]-1])),2) for t in range(5)])

